import{d as c,C as t,o as m,c as p,j as a,a as o,E as r,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第十八章","description":"从大道废与四组反差，辨认仁义、孝慈、忠臣何以成为显著名目。","frontmatter":{"title":"道德经第十八章","description":"从大道废与四组反差，辨认仁义、孝慈、忠臣何以成为显著名目。","category":"guide","aliases":["道德经第十八章","老子第十八章","dao de jing chapter 18"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-18.md","filePath":"daoism/dao-de-jing/chapter-18.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-18.md"},y=c({...b,setup(x){const n=[{id:"the-way-and-emphatic-moral-names",label:"大道废，有仁义",showLabel:!0,sentences:[[{text:"大道",glossary:"dadao"},{text:"废",glossary:"fei"},"，有",{text:"仁",glossary:"ren"},{text:"义",glossary:"yi"},"；"],[{text:"智慧",glossary:"zhihui"},"出，有",{text:"大伪",glossary:"dawei"},"；"]],note:["【白话】大道废失，仁义便被凸显出来；机巧智虑显出，大的伪诈也随之出现。本章把正面名目与失序、造作放在一起，追问它们何以变得显著。","【王弼注择要】「失无为之事。」关于智慧与大伪，注说「行术用明以察奸伪」。王弼着眼于施术察伪，使人识其手段而设法躲避的情形。","【读法】本章的智慧循注取机巧智虑，不等于一切学习与认识。仁义也不能只按反面词理解；问题在于大道失落后，特意标立的善名怎样承担补救。"]},{id:"family-and-state-in-disorder",label:"六亲不和，有孝慈",showLabel:!0,sentences:[[{text:"六亲",glossary:"liuqin"},"不和，有",{text:"孝慈",glossary:"xiaoci"},"；"],["国家昏乱，有",{text:"忠臣",glossary:"zhongchen"},"。"]],note:["【白话】亲属关系不和，孝顺与慈爱才作为特别的德行显出来；国家昏乱，忠臣才格外被辨认、称述。","【王弼注择要】「甚美之名，生于大恶。」「六亲，父子兄弟夫妇也。」注又设想「若六亲自和，国家自治」，则孝慈、忠臣不再成为需要特别指认的名目。","【读法】这里不是说和睦的家庭没有爱，也不是要求忠臣消失。善名之所以格外显著，可能正说明它所补救的关系已失去日常的通顺。"]}],i=[{id:"dadao",term:"大道",sense:1},{id:"fei",term:"废",sense:1},{id:"ren",term:"仁",sense:1,context:"本章放在大道废后的仁义名目中辨其位置，不将仁本身写成恶。"},{id:"yi",term:"义",sense:1},{id:"zhihui",term:"智慧",sense:1},{id:"dawei",term:"大伪",sense:1},{id:"liuqin",term:"六亲",sense:1},{id:"xiaoci",term:"孝慈",sense:1},{id:"zhongchen",term:"忠臣",sense:1}];return(g,e)=>{const s=t("DaoReadingPrelude"),d=t("DaoTextReading"),l=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十八章",tabindex:"-1"},[o("道德经第十八章 "),a("a",{class:"header-anchor",href:"#道德经第十八章","aria-label":'Permalink to "道德经第十八章"'},"​")],-1)),r(s,{title:"美好的名目，为什么与失序并列？",summary:"本章四次以有字提出反差：大道与仁义、智慧与大伪、亲属失和与孝慈、国家昏乱与忠臣。先看这些名目为何突出，再辨对名目的反省与对实际善行的否定有何区别。",points:[{label:"先读",text:"每个有字前，原有的关系发生了什么？"},{label:"再辨",text:"善行一直存在，与善名格外显著是否相同？"},{label:"后想",text:"称赞补救者之后，还能怎样修复日常关系？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(d,{sections:n,glossary:i,tone:"ink",density:"comfortable","aria-label":"《道德经》第十八章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(l,{lines:[{text:"大道废，有仁义。",tone:"看名目所由",guide:"重点不只在有仁义三个字，还在前面的大道废。王弼从失去无为之事、转向标立善名来解释，读时须保留这层关系。"},{text:"六亲不和，有孝慈。",tone:"看关系常态",guide:"孝慈成为被特别赞叹的德行，不等于家庭关系已经和睦。可以既承认具体照顾的价值，又追问为什么它需要如此艰难地被补足。"},{text:"国家昏乱，有忠臣。",tone:"从人回看处境",guide:"忠臣在乱世中的担当值得辨认，但对个人的称颂不能自动回答国家为何昏乱。章末仍把名目放回其生成的处境。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:i}),e[4]||(e[4]=u('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-四组反差都在说同一件事吗" tabindex="-1">象：四组反差都在说同一件事吗？ <a class="header-anchor" href="#象-四组反差都在说同一件事吗" aria-label="Permalink to &quot;象：四组反差都在说同一件事吗？&quot;">​</a></h3><p>它们共同追问失去原有通顺后，哪些名目会变得显著，但细节并不完全相同。仁义、孝慈、忠臣偏重失序之后善名的突出；智慧与大伪还涉及机巧与避察互相生出的关系，不能一概压成有善必有恶的公式。</p><h3 id="理-批评善名-是否就是否定善行" tabindex="-1">理：批评善名，是否就是否定善行？ <a class="header-anchor" href="#理-批评善名-是否就是否定善行" aria-label="Permalink to &quot;理：批评善名，是否就是否定善行？&quot;">​</a></h3><p>王弼用甚美之名来说明问题所在。亲属彼此照顾、臣下承担责任，与将孝慈忠臣立成炫目的名号，是不同层次。本章可以使人反省对名目的依赖，不必据此贬低真实的关爱与担当。</p><h3 id="用-怎样从善名返回关系的修复" tabindex="-1">用：怎样从善名返回关系的修复？ <a class="header-anchor" href="#用-怎样从善名返回关系的修复" aria-label="Permalink to &quot;用：怎样从善名返回关系的修复？&quot;">​</a></h3><p>当一件补救行为受到称赞时，可以继续问它在补什么缺口、能否减少下一次的同类损害。现代生活中的制度与关系不能直接套用古代亲属、君臣结构，但从赞美个人进一步看条件，是可以借用的提问方式。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>感谢救急，也改善常态。</strong> 团队有人反复救火时，既应承认其劳动，也应检查需求、交接和资源为何总出缺口。持续制造危机，再不断树立英雄，未必能让工作变好。</p><p><strong>让关爱落实为日常条件。</strong> 家庭中的照顾若只靠某一个人长期牺牲，可在表达感谢之后讨论分担、时间与支持。这样的现代联想不以否定孝慈为目的，而是使关爱不只在失和与匮乏时才被看见。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近称赞的一次补救，在填补什么长期缺口？除了赞美那个人，我还能怎样改善这段关系的日常条件？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>四组句序与所据 HFL 电子录文核对，正文保留本站标点。</li><li>六亲本页明确采用王弼「父子兄弟夫妇」之说，不混用其他六亲分类。</li><li>智慧依本章王弼注的施术察伪语境解释；不将本章概括成反对所有知识，也不将慈直接套作第六十七章三宝的专门解释。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，011b–012a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
